    def xorOperation(self, n: int, start: int) -> int:
        def pref(x):
            if x < 0:
                return 0
            return [x, 1, x + 1, 0][x % 4]

        h = start >> 1
        return ((pref(h + n - 1) ^ pref(h - 1)) << 1) | (start & n & 1)

