class Solution {
public:
    int xorOperation(int n, int start) {
        auto pref = [](int x) -> int {
            if (x < 0) return 0;
            int m = x & 3;
            if (m == 0) return x;
            if (m == 1) return 1;
            if (m == 2) return x + 1;
            return 0;
        };
        int h = start >> 1;
        return ((pref(h + n - 1) ^ pref(h - 1)) << 1) | (start & n & 1);
    }
};

