class Solution {
    public int xorOperation(int n, int start) {
        int h = start >> 1;
        int r = pref(h + n - 1) ^ pref(h - 1);
        return (r << 1) | (start & n & 1);
    }

    private int pref(int x) {
        if (x < 0) return 0;
        switch (x & 3) {
            case 0: return x;
            case 1: return 1;
            case 2: return x + 1;
            default: return 0;
        }
    }
}

